import { delimiter } from "node:path"

/** What a tool invocation records. */
export const Payload = { separator: delimiter }

/** A tool invocation, built when the module loads. */
export const Exec = { payload: Payload }

/** The extensions Windows tries for a bare command. */
export const defaultPathExtensions = ".COM;.EXE;.BAT;.CMD"

/** The names a bare command may resolve to. */
export function executableNames(name: string): string[] {
  return defaultPathExtensions.split(";").map((extension) => name + extension + delimiter)
}

import { sep } from "node:path"

/** Where a tool build runs. */
export const Options = { root: sep }

/** The tool build, built when the module loads. */
export const ToolBuild = { options: Options }

/** What a capture records. */
export const CapturePayload = { separator: sep }

/** The payload of one capture. */
export const capture = (): { readonly separator: string } => CapturePayload
